"""A tiny UTF-8 byte-pair tokenizer. Python standard library only."""
from collections import Counter
import sys


def merge(tokens, pair, new_id):
    """Replace matching adjacent pairs left to right, without overlap."""
    result = []
    i = 0
    while i < len(tokens):
        if i + 1 < len(tokens) and (tokens[i], tokens[i + 1]) == pair:
            result.append(new_id)
            i += 2
        else:
            result.append(tokens[i])
            i += 1
    return result


class BytePairTokenizer:
    def __init__(self):
        self.vocab = {i: bytes([i]) for i in range(256)}
        self.merges = []

    def train(self, text, num_merges):
        if num_merges < 0:
            raise ValueError("num_merges must be nonnegative")
        self.__init__()  # Each training call starts from the byte baseline.
        tokens = list(text.encode("utf-8"))
        for _ in range(num_merges):
            counts = Counter(zip(tokens, tokens[1:]))
            if not counts:
                break
            # Most frequent pair; lexical order makes ties deterministic.
            pair = min(counts, key=lambda p: (-counts[p], p))
            new_id = len(self.vocab)
            self.vocab[new_id] = self.vocab[pair[0]] + self.vocab[pair[1]]
            self.merges.append((pair, new_id))
            tokens = merge(tokens, pair, new_id)
        return tokens

    def encode(self, text):
        tokens = list(text.encode("utf-8"))
        # Learned order matters: later pairs may contain earlier token IDs.
        for pair, new_id in self.merges:
            tokens = merge(tokens, pair, new_id)
        return tokens

    def decode(self, tokens):
        # A token can contain only part of a UTF-8 character.
        return b"".join(self.vocab[token] for token in tokens).decode("utf-8")


def broken_decode(tokenizer, tokens):
    """Deliberately wrong: assumes each token is a complete character."""
    return "".join(tokenizer.vocab[token].decode("utf-8") for token in tokens)


def lesson():
    tokenizer = BytePairTokenizer()
    text = "abababab"
    print("Baseline:", tokenizer.encode(text))
    trained = tokenizer.train(text, 2)
    for pair, token in tokenizer.merges:
        print("Merge:", pair, "->", token, "bytes:", tokenizer.vocab[token])
    print("Trained:", trained)
    print("Round trip:", tokenizer.decode(trained))
    print("Unseen 'abXab':", tokenizer.encode("abXab"))
    print("Unicode bytes:", list("é".encode("utf-8")))
    print("Fixed Unicode:", tokenizer.decode(tokenizer.encode("é")))


def checks():
    tokenizer = BytePairTokenizer()
    assert tokenizer.encode("abababab") == [97, 98] * 4
    assert tokenizer.train("abababab", 2) == [257, 257]
    assert tokenizer.merges == [((97, 98), 256), ((256, 256), 257)]
    assert tokenizer.encode("abXab") == [256, 88, 256]
    assert merge([97, 97, 97], (97, 97), 256) == [256, 97]
    samples = ["", "a", "abababab", "abXab", "é", "你好", "🙂", "a\n b", "e\u0301"]
    for text in samples:
        ids = tokenizer.encode(text)
        assert tokenizer.decode(ids) == text
        assert b"".join(tokenizer.vocab[i] for i in ids) == text.encode("utf-8")
    assert BytePairTokenizer().train("", 10) == []
    assert BytePairTokenizer().train("a", 10) == [97]
    assert BytePairTokenizer().train("ab", 0) == [97, 98]
    try:
        tokenizer.train("ab", -1)
    except ValueError:
        pass
    else:
        raise AssertionError("negative merge counts must fail")
    print("PASS: baseline, exact merges, unseen bytes, overlap, 9 round trips,")
    print("      byte preservation, empty/single/zero-merge training, negative count")


if __name__ == "__main__":
