"""Local execution receipts and a scoped Claude Stop gate. Standard library only."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys
import time
import tempfile
import uuid

CODE = {'.py', '.pyw', '.js', '.jsx', '.mjs', '.cjs', '.ts', '.tsx', '.sh', '.bash',
        '.zsh', '.fish', '.ps1', '.bat', '.cmd', '.rs', '.go', '.java', '.c', '.cpp',
        '.cxx', '.h', '.hpp', '.cu', '.cuh', '.cs', '.rb', '.php', '.lua', '.kt',
        '.swift', '.m', '.mm', '.scala', '.html', '.css', '.scss', '.ipynb', '.sql'}
MARKER = 'KARPATHY_RUN_RECEIPT='
RUNTIME = Path(__file__).parent / 'runtime'
WORKSPACE = Path(__file__).parent / 'examples'


def snapshot():
    return {str(p.resolve()): digest(p) for p in WORKSPACE.rglob('*')
            if p.is_file() and p.suffix.lower() in CODE}


def state_path(payload):
    key = str(payload.get('session_id', '')) + ':' + str(payload.get('agent_id', ''))
    return RUNTIME / ('state-' + hashlib.sha256(key.encode()).hexdigest() + '.json')


def prepare(payload):
    RUNTIME.mkdir(parents=True, exist_ok=True)
    path = state_path(payload)
    if not path.exists() or json.loads(path.read_text(encoding='utf-8')).get('closed'):
        path.write_text(json.dumps({'baseline': snapshot(), 'started': time.time(), 'closed': False}), encoding='utf-8')


def close_state(payload):
    path = state_path(payload)
    if path.exists():
        state = json.loads(path.read_text(encoding='utf-8'))
        state['closed'] = True
        path.write_text(json.dumps(state), encoding='utf-8')


def digest(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def run(files, command, cwd):
    paths = [Path(cwd).joinpath(p).resolve() for p in files]
    before = {str(p): digest(p) for p in paths}
    started = time.time()
    executable = Path(command[0]).stem.lower()
    python = executable.startswith('python')
    with tempfile.TemporaryDirectory() as temporary:
        trace_path = Path(temporary) / 'executed.json'
        actual = [command[0], str(Path(__file__).with_name('trace_runner.py')), str(trace_path), *command[1:]] if python else command
        environment = dict(os.environ, PYTHONIOENCODING='utf-8', PYTHONUTF8='1')
        result = subprocess.run(actual, cwd=cwd, capture_output=True, text=True,
                                encoding='utf-8', errors='replace', timeout=120, env=environment)
        executed = set(json.loads(trace_path.read_text(encoding='utf-8'))) if trace_path.exists() else set()
    # Non-Python commands may run, but arguments alone cannot prove file execution.
    # They therefore receive no file coverage until a runtime tracer is supplied.
    receipt = {'started': started, 'finished': time.time(), 'command': command,
               'cwd': str(Path(cwd).resolve()), 'exit_code': result.returncode,
               'files': {p: h for p, h in before.items() if p in executed},
               'unchanged': all(digest(p) == before[str(p)] for p in paths)}
    RUNTIME.mkdir(parents=True, exist_ok=True)
    ident = uuid.uuid4().hex
    (RUNTIME / f'receipt-{ident}.json').write_text(json.dumps(receipt), encoding='utf-8')
    sys.stdout.write(result.stdout)
    sys.stderr.write(result.stderr)
    print(MARKER + json.dumps({'id': ident}, ensure_ascii=True))
    return result.returncode


def read_transcript(path):
    return [json.loads(line) for line in Path(path).read_text(encoding='utf-8').splitlines() if line.strip()]


def blocks(rows):
    for row in rows:
        content = row.get('message', {}).get('content', [])
        if isinstance(content, list):
            yield from (b for b in content if isinstance(b, dict))


def current_turn(rows):
    start = 0
    for i, row in enumerate(rows):
        content = row.get('message', {}).get('content', [])
        # Tool results are user messages too; only an actual human text starts a turn.
        if row.get('type') == 'user' and not row.get('isMeta') and (isinstance(content, str) or
                any(b.get('type') == 'text' for b in content if isinstance(b, dict))):
            start = i
    return rows[start:]


def check(payload):
    kind = payload.get('agent_type', '')
    path = payload.get('agent_transcript_path') or payload.get('transcript_path')
    if kind and kind != 'karpathy':
        return None
    if not path:
        return 'Karpathy execution evidence unavailable.' if kind == 'karpathy' else None
    rows = read_transcript(path)
    if not payload.get('agent_transcript_path'):
        rows = current_turn(rows)
    items = list(blocks(rows))
    scoped = kind == 'karpathy' or any(
        b.get('type') == 'tool_use' and
        ((b.get('name') == 'Skill' and b.get('input', {}).get('skill', '').split(':')[-1] == 'karpathy-teach') or
         (b.get('name') in {'Agent', 'Task'} and b.get('input', {}).get('subagent_type') == 'karpathy'))
        for b in items)
    if not scoped:
        return None
    edits = {}
    attempted_edits = []
    calls = {}
    results = {}
    for index, block in enumerate(items):
        if block.get('type') == 'tool_use':
            calls[block.get('id')] = block
            if block.get('name') in {'Write', 'Edit', 'MultiEdit'}:
                filename = block.get('input', {}).get('file_path', '')
                if Path(filename).suffix.lower() in CODE:
                    attempted_edits.append((str(Path(payload.get('cwd', '.')).joinpath(filename).resolve()), index, block.get('id')))
        elif block.get('type') == 'tool_result':
            results[block.get('tool_use_id')] = (index, block)
    # A failed tool call did not edit a file. Missing successful receipts are conservative.
    for filename, index, ident in attempted_edits:
        if ident not in results or not results[ident][1].get('is_error'):
            edits[filename] = index
    state_file = state_path(payload)
    state = json.loads(state_file.read_text(encoding='utf-8')) if state_file.exists() else None
    if state:
        current = snapshot()
        for filename, value in current.items():
            if state['baseline'].get(filename) != value:
                edits.setdefault(filename, -1)
    if not edits:
        return None
    covered = set()
    for ident, (index, result) in results.items():
        call = calls.get(ident, {})
        if call.get('name') not in {'Bash', 'PowerShell'} or result.get('is_error'):
            continue
        content = result.get('content', '')
        text = content if isinstance(content, str) else '\n'.join(b.get('text', '') for b in content if isinstance(b, dict))
        for line in text.splitlines():
            if not line.startswith(MARKER):
                continue
            try:
                ident = json.loads(line[len(MARKER):]).get('id', '')
                if not isinstance(ident, str) or len(ident) != 32 or not all(c in '0123456789abcdef' for c in ident):
                    continue
                command = call.get('input', {}).get('command', '')
                if 'run_gate.py' not in command or '--run' not in command:
                    continue
                receipt = json.loads((RUNTIME / f'receipt-{ident}.json').read_text(encoding='utf-8'))
                if receipt.get('exit_code') != 0 or not receipt.get('unchanged'):
                    continue
                if state and receipt['started'] < state['started']:
                    continue
                for filename, expected in receipt.get('files', {}).items():
                    filename = str(Path(filename).resolve())
                    if filename in edits and index > edits[filename] and digest(filename) == expected:
                        covered.add(filename)
            except (ValueError, OSError, TypeError):
                continue
    missing = set(edits) - covered
    if missing:
        if payload.get('stop_hook_active') and payload.get('last_assistant_message', '').startswith('Execution blocked:'):
            print('Karpathy execution exception reported; code remains unverified.', file=sys.stderr)
            return None
        return 'Karpathy rule, run it before you say it works. Missing successful current-file execution receipts: ' + ', '.join(sorted(missing))
    return None


def main():
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, 'reconfigure'):
            stream.reconfigure(encoding='utf-8', errors='backslashreplace')
    parser = argparse.ArgumentParser()
    parser.add_argument('--run', action='store_true')
    parser.add_argument('--scope', action='store_true')
    parser.add_argument('--file', action='append', default=[])
    parser.add_argument('--cwd', default=os.getcwd())
    parser.add_argument('command', nargs=argparse.REMAINDER)
    args = parser.parse_args()
    if args.run:
        command = args.command[1:] if args.command[:1] == ['--'] else args.command
        if not args.file or not command:
            parser.error('--run requires --file and a command after --')
        return run(args.file, command, args.cwd)
    payload = json.load(sys.stdin)
    if args.scope:
        payload['agent_type'] = 'karpathy'
    if payload.get('hook_event_name') == 'PreToolUse':
        prepare(payload)
        return 0
    try:
        reason = check(payload)
    except (OSError, ValueError, TypeError) as error:
        # Fail visibly for scoped work, never block unrelated agents.
        reason = f'Karpathy execution evidence unreadable: {type(error).__name__}' if payload.get('agent_type') == 'karpathy' else None
    if reason:
        print(json.dumps({'decision': 'block', 'reason': reason}))
    else:
        close_state(payload)
    return 0


if __name__ == '__main__':
    raise SystemExit(main())

